"""Render bounded delivery from receipts; cannot authorize additional experiments."""
from contracts import *

def report(out,receipt):
    v=read(receipt);commands=[read(p) for p in (out/'commands').glob('*.json')]
    resources=dict(cpu_seconds_sampled=sum(c['cpu_seconds_sampled'] for c in commands),peak_rss_bytes_sampled=max([c['peak_rss_bytes_sampled'] for c in commands]+[0]),wall_seconds_profiled=sum(c['wall_seconds'] for c in commands),commands=len(commands),failed_commands=sum(c['exit_status']!=0 for c in commands),independent_review_cpu_seconds=.265625,limitations='CPU/RSS polled at .05 seconds; startup/exit sampling loss, supervisor, Git, reporting, and interactive orchestration overhead not comprehensively profiled. Reviewer toy CPU measured after imports. No paid calls or dataset/model downloads.')
    resources['accounted_cpu_subtotal']=resources['cpu_seconds_sampled']+resources['independent_review_cpu_seconds']
