    counts=dict(attempted_optimizer_records=len(starts),completed_optimizer_records=len(records),shared_fits=sum(x['meta']['kind']=='shared' for x in records),adaptation_batches=sum(x['meta']['kind']=='personal' for x in records),person_solves=sum(x['meta']['person_solves'] for x in records),scientific_retries=0)
    numerical={r:read(out/(r+'_numerical.json')) for r in REAL if (out/(r+'_numerical.json')).exists()}
    summary=dict(status=status,audit_state=v['state'],qualification=q,numerical=numerical,realization_gates=summaries,counts=counts,resources=resources,forward_replay=complete,source_revision=read(out/'publication.json')['commit'],assignment=BASE)
